function badgeCss(opts){
  opts=opts||{};
  var bg=opts.bg||'#5E6AD2';
  var color=opts.color||'#ffffff';
  var radius=opts.radius!=null?opts.radius:999;
  var px=opts.padX!=null?opts.padX:10;
  var py=opts.padY!=null?opts.padY:3;
  var size=opts.size!=null?opts.size:12;
  var L=[];
  L.push('.badge {');
  L.push('  display: inline-flex;');
  L.push('  align-items: center;');
  L.push('  background: '+bg+';');
  L.push('  color: '+color+';');
  L.push('  border-radius: '+radius+'px;');
  L.push('  padding: '+py+'px '+px+'px;');
  L.push('  font-size: '+size+'px;');
  L.push('  font-weight: 600;');
  L.push('  line-height: 1.4;');
  L.push('}');
  return L.join('\n');
}

var EXPORTS={badgeCss:badgeCss};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BadgeForgePure = EXPORTS; }
